32|// Companion panel: illustrates the selected passage or the current scene.
33|// The client sends ordinals and ids only, never text. The scene id comes
34|// from the route, never from a DOM scan.
35|export function PicturePanel({
36|  bookId,
37|  textVersion,
38|  sceneId,
39|}: {
40|  bookId: string;
41|  textVersion: string;
42|  sceneId: string;
43|}) {
44|  const [card, setCard] = useState<Card>({ phase: "idle" });
45|  const [selTop, setSelTop] = useState<number | null>(null);
46|  const [selLeft, setSelLeft] = useState<number | null>(null);
47|  const pollLeft = useRef(0);
48|
49|  const request = useCallback(
50|    async (body: unknown) => {
51|      setCard({ phase: "loading" });
52|      pollLeft.current = POLL_MAX;
53|      for (;;) {
54|        let res: ImageResponse;
55|        try {
56|          res = await postImage(body);
57|        } catch {
58|          setCard({ phase: "error", message: "No se pudo generar la imagen. Vuelve a intentarlo." });
59|          return;
60|        }
61|        if (res.status === "ready") {
62|          setCard({ phase: "ready", url: res.url, caption: res.caption, cached: res.cached });
63|          return;
64|        }
65|        if (res.status === "error") {
66|          setCard({ phase: "error", message: res.message });
67|          return;
68|        }
69|        pollLeft.current -= 1;
70|        if (pollLeft.current <= 0) {
71|          setCard({
72|            phase: "error",
73|            message: "La imagen tarda más de lo esperado. Vuelve a intentarlo.",
74|          });
75|          return;
76|        }
77|        await new Promise((done) => setTimeout(done, POLL_MS));
