6|// session values when nothing plays yet.
7|export function mixOffSelection(
8|  selection: MusicSelection,
9|  playing: Pick<Track, "soundtrack" | "style"> | null,
10|): MusicSelection {
11|  return {
12|    mode: "soundtrack",
13|    soundtrackId: playing?.soundtrack ?? selection.soundtrackId,
14|    style: playing?.style ?? selection.style,
15|  };
