14|import type { MusicManifest, MusicSelection, SceneSignal, Track } from "./music";
15|import type { Vector8 } from "./types";
16|import { EMOTIONS } from "./types";
17|
18|function vec(top: string): Vector8 {
19|  const v = Object.fromEntries(EMOTIONS.map((id) => [id, 0.01])) as Record<string, number>;
20|  v[top] = 0.93;
21|  return v as Vector8;
22|}
23|
24|function signal(top: string, intensity = 0.5, tempo = 0.5): SceneSignal {
25|  return { vector: vec(top), intensity, tempo };
26|}
27|
28|function track(
29|  id: string,
30|  top: string,
31|  soundtrack: string,
32|  style: string,
33|  intensity = 0.5,
34|  tempo = 0.5,
35|): Track {
36|  return {
37|    id,
38|    src: `/music/${id}.mp3`,
39|    title: id,
40|    emotion: top as Track["emotion"],
41|    vector: vec(top),
42|    intensity,
43|    tempo,
44|    durationSec: 120,
45|    startSec: 0,
46|    loop: true,
47|    soundtrack,
48|    style,
49|  };
