52|// Two orchestral soundtracks with overlapping emotions (orch-b has no
53|// tristeza), one piano soundtrack with some emotions, one electronic
54|// soundtrack that must never play while the style is orchestral.
55|const manifest: MusicManifest = {
56|  version: 3,
57|  styles: [
58|    { id: "orchestral", name: "Orquesta" },
59|    { id: "piano", name: "Piano" },
60|    { id: "electronic", name: "Electronica" },
61|  ],
62|  soundtracks: [
63|    { id: "orch-a", name: "A", style: "orchestral" },
64|    { id: "orch-b", name: "B", style: "orchestral" },
65|    { id: "piano-a", name: "P", style: "piano" },
66|    { id: "elec", name: "E", style: "electronic" },
67|  ],
68|  playlists: [],
69|  tracks: [
70|    track("a-calma", "calma", "orch-a", "orchestral"),
71|    track("a-calm2", "calma", "orch-a", "orchestral", 0.52),
72|    track("a-triste", "tristeza", "orch-a", "orchestral"),
73|    track("a-far", "calma", "orch-a", "orchestral", 0.9, 0.9),
74|    track("b-calma", "calma", "orch-b", "orchestral"),
75|    track("b-alegre", "alegria", "orch-b", "orchestral"),
76|    track("e-calma", "calma", "elec", "electronic"),
77|    track("p-calma", "calma", "piano-a", "piano"),
78|    track("p-mist", "misterio", "piano-a", "piano"),
79|  ],
80|};
81|
82|const orchA: MusicSelection = { mode: "soundtrack", soundtrackId: "orch-a", style: "orchestral" };
83|const orchB: MusicSelection = { mode: "soundtrack", soundtrackId: "orch-b", style: "orchestral" };
84|const orchRandom: MusicSelection = { mode: "random", soundtrackId: "orch-a", style: "orchestral" };
