105|  it("home is the session soundtrack, or the style set when none is set", () => {
106|    const styleTracks = candidatesFor(orchA, manifest);
107|    expect(homeTracks(orchA, styleTracks).map((t) => t.id).sort()).toEqual(
108|      ["a-calma", "a-calm2", "a-far", "a-triste"].sort(),
109|    );
110|    expect(
111|      homeTracks({ mode: "soundtrack", soundtrackId: "gone", style: "orchestral" }, styleTracks),
112|    ).toHaveLength(styleTracks.length);
113|  });
