143|    const run = () =>
144|      tickScheduler(playing("a-far", 0), signal("calma"), manifest, 100, orchRandom(() => 0.99));
145|    expect(run().switchToId).toBe(run().switchToId);
146|    expect(run().switchToId).not.toBe("a-far");
147|  });
148|
149|  it("never leaves the style", () => {
150|    let d = observeScene(initScheduler(), "s1", signal("calma"), manifest, 0, orchRandom());
151|    for (const [scene, top, at] of [
