12|} from "@/core/music";
13|import type { MusicManifest, MusicSelection, SceneSignal, Track } from "@/core/music";
14|import {
15|  enterPlaylist,
16|  exitPlaylist,
17|  initScheduler,
18|  noteTrackEnded,
19|  observeScene,
20|  requestNext,
