29|export interface SlimScene {
30|  id: string;
31|  ch: number;
32|  emotion: SceneSignal | null;
33|}
34|
35|// Route entries use the short dwell; scoring and hysteresis are untouched.
36|function entryDwell(): { dwellSec: number } {
37|  return { dwellSec: MUSIC_CONFIG.sceneEntryDwellSec };
38|}
39|
40|// The Chopin playlist, when the manifest defines it with tracks. The
41|// button stays hidden otherwise, and the player never persists the playlist.
42|function findChopinPlaylist(manifest: MusicManifest) {
43|  const found = manifest.playlists.find((p) => p.id === CHOPIN_PLAYLIST_ID) ?? null;
44|  return found && found.trackIds.length > 0 ? found : null;
