47|// Client container: cues music on scene entry only, from the route id.
48|// Sub-page moves never reach the scheduler. Params can lag a render, so
49|// the last observed id is compared before every observe call.
50|export function Reader({ scenes, children }: { scenes: SlimScene[]; children: React.ReactNode }) {
51|  const routeParams = useParams();
52|  const param = routeParams?.sceneId;
53|  const routeSceneId = typeof param === "string" ? param : null;
54|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
55|  const [selection, setSelection] = useState<MusicSelection | null>(null);
56|  const [musicFailed, setMusicFailed] = useState(false);
57|  const [currentId, setCurrentId] = useState<string | null>(null);
58|  const [replayNonce, setReplayNonce] = useState(0);
59|  const [fadeSec, setFadeSec] = useState(0);
60|  const [playlistOn, setPlaylistOn] = useState(false);
