96|      if (!st.manifest || !st.selection) return;
97|      const signal = st.byId.get(sceneId) ?? null;
98|      applyDecision(
99|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
100|          selection: st.selection,
101|          rng: Math.random,
102|        }, entryDwell()),
103|      );
104|    },
105|    [applyDecision],
106|  );
107|
108|  useEffect(() => {
109|    let cancelled = false;
110|    fetch("/music/manifest.json")
111|      .then((res) => {
112|        if (!res.ok) throw new Error(`manifest ${res.status}`);
