141|  useEffect(() => {
142|    // Settle an expired entry dwell, or re-check the scene after a hold.
143|    const timer = window.setInterval(() => {
144|      const st = liveRef.current;
145|      if (!st.manifest || !st.selection || !st.routeSceneId) return;
146|      const sceneId = schedRef.current.pendingSceneId ?? st.routeSceneId;
147|      const signal = st.byId.get(sceneId) ?? null;
148|      applyDecision(
149|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
150|          selection: st.selection,
151|          rng: Math.random,
152|        }, entryDwell()),
153|      );
154|    }, 1000);
155|    return () => window.clearInterval(timer);
156|  }, [applyDecision]);
157|
158|  function skip() {
159|    const st = liveRef.current;
160|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
161|    const signal = st.byId.get(st.routeSceneId) ?? null;
162|    applyDecision(
163|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
