174|    if (!playlist) return;
175|    if (st.playlistOn) {
176|      const signal = (st.routeSceneId && st.byId.get(st.routeSceneId)) || null;
177|      applyDecision(
178|        exitPlaylist(schedRef.current, signal ?? null, st.manifest, nowSec(), {
179|          selection: st.selection,
180|          rng: Math.random,
181|        }),
182|      );
183|      setPlaylistOn(false);
184|      return;
185|    }
186|    applyDecision(enterPlaylist(schedRef.current, st.manifest, playlist.id, nowSec()));
187|    setPlaylistOn(true);
188|  }
189|
190|  function changeStyle(style: string) {
191|    const st = liveRef.current;
192|    if (!st.manifest || !st.selection || !st.routeSceneId || st.playlistOn) return;
193|    if (style === st.selection.style) return;
194|    const signal = st.byId.get(st.routeSceneId) ?? null;
