238|            track={track}
239|            replayNonce={replayNonce}
240|            fadeSec={fadeSec}
241|            soundtrackCredit={soundtrackCredit}
242|            canSkip={canSkip}
243|            onSkip={skip}
244|            styles={stylesWithTracks}
245|            styleId={selection?.style ?? null}
246|            onStyleChange={changeStyle}
247|            onEnded={ended}
248|            playlistOn={playlistOn}
249|            playlistLabel={activePlaylist?.label ?? null}
250|            onTogglePlaylist={togglePlaylist}
251|            controlsDisabled={playlistOn}
252|          />
253|        )}
254|      </div>
255|      {children}
256|    </>
257|  );
